import ghidra.app.script.GhidraScript;
import ghidra.app.util.PseudoInstruction;
import ghidra.program.model.lang.*;
import ghidra.program.model.mem.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import java.nio.file.*;import java.util.*;import java.math.BigInteger;import java.security.*;import com.google.gson.*;
public class C6000ParallelPeersTest extends GhidraScript {
 long n(JsonObject r,String key){return r.get(key).getAsLong();}
 String sha(byte[] value)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}
 void equal(Object expected,Object actual,String message){if(!Objects.equals(expected,actual))throw new AssertionError(message+" expected="+expected+" actual="+actual);}
 void create(long pc)throws Exception{var at=toAddr(pc);var context=new ProcessorContextImpl(currentProgram.getLanguage());var value=currentProgram.getProgramContext().getRegisterValue(currentProgram.getLanguage().getContextBaseRegister(),at);if(value!=null)context.setRegisterValue(value);var memory=new DumbMemBufferImpl(currentProgram.getMemory(),at);var prototype=currentProgram.getLanguage().parse(memory,context,false);currentProgram.getListing().createInstruction(at,prototype,memory,context,0);}
 protected void run()throws Exception{
  var args=getScriptArgs();var rows=JsonParser.parseString(Files.readString(Paths.get(args[0]))).getAsJsonArray();var folder=Paths.get(args[1]);Files.createDirectories(folder);c6000.C6000PacketContext.prime(currentProgram,monitor);var anchors=new JsonArray();int expected=0;long source=0x1000,end=0x1000+rows.size()*0x100;
  for(var element:rows){var row=element.getAsJsonObject();String name=row.get("name").getAsString();long at=n(row,"anchor"),peer=n(row,"peer"),base=n(row,"base");currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_flow_delay"),toAddr(at),toAddr(at),BigInteger.ZERO);create(at);long ownerEnd=at+currentProgram.getListing().getInstructionAt(toAddr(at)).getLength()-1;if(name.equals("anchor_partial_owner"))ownerEnd=at+1;if(name.equals("already_defined"))ownerEnd=peer+3;if(name.equals("partial_owner")||name.equals("defined_partial_bridge"))ownerEnd=peer+1;currentProgram.getFunctionManager().createFunction("peer_"+name,toAddr(base),new AddressSet(toAddr(base),toAddr(ownerEnd)),SourceType.USER_DEFINED);
   if(name.equals("late_data"))createData(toAddr(peer+4),ghidra.program.model.data.DWordDataType.dataType);if(name.equals("data_start"))createData(toAddr(peer),ghidra.program.model.data.DWordDataType.dataType);if(name.equals("data_suffix"))createData(toAddr(peer+3),ghidra.program.model.data.ByteDataType.dataType);if(name.equals("instruction_suffix")){currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_is16"),toAddr(peer+2),toAddr(peer+2),BigInteger.ONE);create(peer+2);}if(name.equals("foreign_owner"))currentProgram.getFunctionManager().createFunction("different_peer_owner",toAddr(peer),new AddressSet(toAddr(peer),toAddr(peer+3)),SourceType.USER_DEFINED);if(name.equals("stale_context"))currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_is16"),toAddr(peer),toAddr(peer),BigInteger.ZERO);if(name.equals("already_defined")||name.equals("defined_partial_bridge"))create(peer);
   if(name.equals("annotations")){setEOLComment(toAddr(peer),"keep undefined peer comment");setPlateComment(toAddr(peer),"keep undefined peer plate");currentProgram.getSymbolTable().createLabel(toAddr(peer),"annotated_peer",SourceType.USER_DEFINED);currentProgram.getReferenceManager().addMemoryReference(toAddr(peer),toAddr(base+128),RefType.DATA,SourceType.USER_DEFINED,0);currentProgram.getReferenceManager().addMemoryReference(toAddr(base+128),toAddr(peer),RefType.DATA,SourceType.USER_DEFINED,0);}
   if(name.equals("nested_window")){var cls=Class.forName("c6000.C6000DelaySlots$Reader");var constructor=cls.getDeclaredConstructor(ghidra.program.model.listing.Program.class);constructor.setAccessible(true);var reader=constructor.newInstance(currentProgram);var method=cls.getDeclaredMethod("window",ghidra.program.model.listing.Instruction.class,ghidra.util.task.TaskMonitor.class);method.setAccessible(true);equal(null,method.invoke(reader,currentProgram.getListing().getInstructionAt(toAddr(at)),monitor),"nested full window still refuses");}
   byte[] raw=new byte[currentProgram.getListing().getInstructionAt(toAddr(at)).getLength()];currentProgram.getMemory().getBytes(toAddr(at),raw);var anchor=new JsonObject();anchor.addProperty("address",at);anchor.addProperty("allowed_end",n(row,"allowed_end"));anchor.addProperty("expected_bytes",HexFormat.of().formatHex(raw));anchors.add(anchor);expected+=row.get("expected").getAsInt();
  }
  byte[] raw=new byte[(int)(end-source)];currentProgram.getMemory().getBytes(toAddr(source),raw);var manifest=new JsonObject();manifest.addProperty("schema",1);manifest.addProperty("language_id",currentProgram.getLanguageID().getIdAsString());var image=new JsonObject();image.addProperty("start",source);image.addProperty("length",raw.length);image.addProperty("sha256",sha(raw));manifest.add("source",image);manifest.add("anchors",anchors);var manifestPath=folder.resolve("manifest.json");var report=folder.resolve("report.json");Files.writeString(manifestPath,new GsonBuilder().setPrettyPrinting().create().toJson(manifest));long before=currentProgram.getModificationNumber();byte[] manifestBefore=Files.readAllBytes(manifestPath);boolean samePath=false;try{runScript(Paths.get(args[2]).getFileName().toString(),new String[]{manifestPath.toString(),manifestPath.getParent().resolve("unused/../"+manifestPath.getFileName()).toString()});}catch(IllegalArgumentException expectedFailure){if(!expectedFailure.getMessage().contains("manifest and report paths must differ"))throw expectedFailure;samePath=true;}if(!samePath)throw new AssertionError("same normalized manifest/report path accepted");equal(before,currentProgram.getModificationNumber(),"same path did not mutate program");if(!Arrays.equals(manifestBefore,Files.readAllBytes(manifestPath)))throw new AssertionError("same path changed manifest");runScript(Paths.get(args[2]).getFileName().toString(),new String[]{manifestPath.toString(),report.toString()});equal(before,currentProgram.getModificationNumber(),"default report is read-only");var proof=JsonParser.parseString(Files.readString(report)).getAsJsonObject();equal(expected,proof.get("eligible_count").getAsInt(),"proved peer count");String review=sha(Files.readAllBytes(report));
  long guarded=currentProgram.getModificationNumber();boolean wrongHash=false;try{runScript(Paths.get(args[2]).getFileName().toString(),new String[]{manifestPath.toString(),report.toString(),"apply","0".repeat(64)});}catch(IllegalArgumentException expectedFailure){if(!expectedFailure.getMessage().contains("review report SHA changed"))throw expectedFailure;wrongHash=true;}if(!wrongHash)throw new AssertionError("wrong review hash accepted");equal(guarded,currentProgram.getModificationNumber(),"wrong review hash did not mutate");
  var badManifest=manifest.deepCopy();badManifest.getAsJsonObject("source").addProperty("sha256","0".repeat(64));var badPath=folder.resolve("bad-manifest.json");Files.writeString(badPath,new Gson().toJson(badManifest));boolean badSource=false;try{runScript(Paths.get(args[2]).getFileName().toString(),new String[]{badPath.toString(),folder.resolve("bad-report.json").toString()});}catch(IllegalArgumentException expectedFailure){if(!expectedFailure.getMessage().contains("pinned source SHA mismatch"))throw expectedFailure;badSource=true;}if(!badSource)throw new AssertionError("wrong source hash accepted");equal(guarded,currentProgram.getModificationNumber(),"wrong source hash did not mutate");
  for(var element:rows){var row=element.getAsJsonObject();if(row.get("name").getAsString().equals("stale_context"))currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_is16"),toAddr(n(row,"peer")),toAddr(n(row,"peer")),BigInteger.ONE);}long drifted=currentProgram.getModificationNumber();boolean driftRejected=false;try{runScript(Paths.get(args[2]).getFileName().toString(),new String[]{manifestPath.toString(),report.toString(),"apply",review});}catch(IllegalArgumentException expectedFailure){if(!expectedFailure.getMessage().contains("reviewed plan changed"))throw expectedFailure;driftRejected=true;}if(!driftRejected)throw new AssertionError("changed reviewed context accepted");equal(drifted,currentProgram.getModificationNumber(),"plan drift did not mutate");for(var element:rows){var row=element.getAsJsonObject();if(row.get("name").getAsString().equals("stale_context"))currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_is16"),toAddr(n(row,"peer")),toAddr(n(row,"peer")),BigInteger.ZERO);}
  runScript(Paths.get(args[2]).getFileName().toString(),new String[]{manifestPath.toString(),report.toString(),"apply",review});var applied=JsonParser.parseString(Files.readString(report)).getAsJsonObject();equal(expected,applied.get("created_count").getAsInt(),"created peer count");
  for(var element:rows){var row=element.getAsJsonObject();long peer=n(row,"peer"),base=n(row,"base");String name=row.get("name").getAsString();if(row.get("expected").getAsInt()>0){var instruction=currentProgram.getListing().getInstructionAt(toAddr(peer));if(instruction==null)throw new AssertionError("missing peer "+name);equal((int)n(row,"width"),instruction.getLength(),"physical peer width");if(currentProgram.getListing().getInstructionAt(toAddr(peer+instruction.getLength()))!=null)throw new AssertionError("ordinary flow followed "+name);}
   else if(!name.equals("already_defined")&&!name.equals("defined_partial_bridge")&&currentProgram.getListing().getInstructionAt(toAddr(peer))!=null)throw new AssertionError("conflicting peer overwritten "+name);
   if(name.equals("annotations")){equal("keep undefined peer comment",getEOLComment(toAddr(peer)),"EOL preserved");equal("keep undefined peer plate",getPlateComment(toAddr(peer)),"plate preserved");equal("annotated_peer",currentProgram.getSymbolTable().getPrimarySymbol(toAddr(peer)).getName(),"label preserved");}
   if(name.equals("defined_partial_bridge")&&currentProgram.getListing().getInstructionAt(toAddr(peer+4))!=null)throw new AssertionError("recovered beyond partial-owned defined bridge");
   if(name.equals("stale_context"))equal(BigInteger.ZERO,currentProgram.getProgramContext().getValue(currentProgram.getRegister("c_is16"),toAddr(peer),false),"stale context retained");
  }
  long after=currentProgram.getModificationNumber();runScript(Paths.get(args[2]).getFileName().toString(),new String[]{manifestPath.toString(),folder.resolve("repeat-report.json").toString()});equal(after,currentProgram.getModificationNumber(),"repeat report read-only");var repeat=JsonParser.parseString(Files.readString(folder.resolve("repeat-report.json"))).getAsJsonObject();equal(0,repeat.get("eligible_count").getAsInt(),"idempotent discovery");println("C6000_PARALLEL_PEER_TEST_OK cases="+rows.size()+" created="+expected+" samePathRefused=true");
 }
}
